using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;

namespace WordChains {

    // Words come from backend/domain/words.txt, generated by scripts/update-words.py.
    public class WordList {
        const string ResourceName = "WordChains.words.txt";

        public static readonly List<string> Dictionary = Load();
        static readonly HashSet<string> Known = new HashSet<string>(Dictionary);

        public static bool Contains(string word) => Known.Contains(word);

        static List<string> Load() {
            using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName);
            using var reader = new StreamReader(stream);
            return reader.ReadToEnd().Split('\n').Where(w => w.Length > 0).ToList();
        }
    }
}
